INSERT INTO chat_group_join_request (
    group_id, user_id, nickname, status, create_time, update_time
) VALUES (
    #{groupId}, #{userId}, #{nickname}, #{status}, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
)

mapper.select:
SELECT r.id AS request_id, r.group_id, r.user_id, r.nickname, u.username, u.avatar_url, r.status, r.reviewer_id, r.review_time, r.reject_reason, r.create_time, r.update_time FROM chat_group_join_request r LEFT JOIN app_user u ON u.id = r.user_id AND u.is_deleted = 0 WHERE r.group_id = #{groupId} AND r.is_deleted = 0
AND r.status = #{status}
ORDER BY r.create_time DESC
